ModulinoKnob knob; // create knob object

void setup(void) {
    Serial.begin(115200);
    Serial.printf("Hello! ST77xx TFT Test\n");


    cc1200.pin_sck = 4; //Default 5, GPIO5 is a pull-up strapping pin.
    cc1200.spi = new SPIClass(VSPI);

    // // OR use this initializer (uncomment) if using a 1.9" 170x320 TFT:
    tft.init(170, 320);           // Init ST7789 170x320

    // // SPI speed defaults to SPI_DEFAULT_FREQ defined in the library, you can override it here
    // // Note that speed allowable depends on chip and quality of wiring, if you go too fast, you
    // // may end up with a black screen some times, or all the time.
    tft.setSPISpeed(40000000); // HSPI Speed = 40 MHz
    Serial.printf("Initialized");
    uint16_t time = millis();
    tft.fillScreen(ST77XX_BLACK);


    // # Different Test Cases
    // frequencyScreen();
    // testdemoA();
    //demoAdafruitDriver();
    testDemoMenue();
    
    time = millis() - time;
    Serial.println(time, DEC);

    Modulino.begin();
    // Detect and connect to knob module
    knob.begin();
    delay(500);
}

void loop() {
  
  // Get the current position value of the knob
  int position = knob.get();
  // set knob limits
  if (move >= 4) {
    move = 1;
  }
  if (move == -2) {
    move = 1;
  }

  Serial.print("Current position is: ");
  Serial.println(move);
  

  // Check if the knob has been pressed (clicked)
  bool click = knob.isPressed();
  // Get the rotation direction
  int8_t direction = knob.getDirection();


  if(click){
    Serial.println("Clicked!");
    press = true;
  }

  if (direction == 1) {
    Serial.println("Rotated clockwise");
    move++;
  } else if (direction == -1) {
    Serial.println("Rotated counter-clockwise");
    move--;
  }

  displayInteract(move, press);

  delay(100); // optional small delay to reduce serial spam
}